import { useState } from "react";
import { Card } from "@/shared/ui/data/Card";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";

// The real card also renders a live ThemeScope+SelfWiredKitRenderer preview of the SDK demo spec
// (`@/shared/ui/kit`, `@/shared/ui/spec`). Omitted here: `@/shared/ui/kit`'s ThemeScope is the exact
// broken module chain behind this session's known pre-existing AlgorithmsInspector failure (module not
// found: shared/ui/theme / ThemeScope / ThemeProvider) — not fixable from this vendoring pass. The
// picker row + description below is the genuinely achievable, presentational part.
//
// `kitThemes` is a preview-only stand-in for the store-hydrated theme collection (app-internal).
const KIT_THEMES = [
  { id: "default", label: "Default", description: "The base look — no overrides." },
  { id: "soft", label: "Soft", description: "Lower-contrast surfaces, gentler borders." },
  { id: "contrast", label: "Contrast", description: "Higher-contrast surfaces for readability." },
  { id: "warm", label: "Warm", description: "A warmer accent and panel tint." },
];

export function KitThemeCard() {
  const [kitTheme, setKitTheme] = useState("default");
  const active = KIT_THEMES.find((t) => t.id === kitTheme) ?? KIT_THEMES[0];

  return (
    <Card title="Kit theme" hint="restyles every card, button, field & chip">
      <Stack gap="md">
        <Row gap="sm" wrap>
          {KIT_THEMES.map((t) => (
            <Button
              key={t.id}
              variant={t.id === kitTheme ? "primary" : "default"}
              title={t.description}
              onClick={() => setKitTheme(t.id)}
            >
              {t.label}
            </Button>
          ))}
        </Row>
        <Text tone="dim" size="sm">{active.description}</Text>

        <Box>
          <Text tone="muted" size="xs" mono style={{ textTransform: "uppercase", letterSpacing: ".06em" }}>
            Preview
          </Text>
          <Box style={{ marginTop: 6, maxWidth: 340, padding: 14, border: "1px dashed var(--border-soft)", borderRadius: 8, color: "var(--fg-dim)", fontSize: 11.5 }}>
            Live spec × theme preview renders here in the real app.
          </Box>
        </Box>
      </Stack>
    </Card>
  );
}
